const { pipeline } = require ('node:stream/promises')
const express = require ('express')
const cds = require ('../../index')
const LOG = cds.log ('hcql')


class HCQLAdapter extends require('./http') {

  get router() {
    const bpo = this.body_parser_options
    const router = super.router
      .get ('/', this.describe.bind(this))
      .use (express.json(bpo)) //> for application/json -> cqn
      .use (express.text(bpo)) //> for text/plain -> cql -> cqn
      .use (log_request)
    if (process.env.NODE_ENV !== 'production')
      router.use (['/:entity/:id','/:entity'], this.shortcut.bind(this))
    router.use ('/:event', this.action.bind(this))
    router.use (this.query.bind(this))
    return router
  }


  /**
   * Handler for /?describe requests.
   * @type {express.RequestHandler}
   */
  describe (req, res) {
    LOG.info (req.method, decodeURI (req.baseUrl + req.path), {...req.query})
    const srv = this.service, response = { service: srv.name }
    const { describe } = req.query

    // Handle special describe requests like $csn
    if (describe === '$csn') return res.json (
      cds.minify (this.service.model, response)
    )

    // If no entities or actions are requested, return a service summary.
    const entities = Object.keys(srv.entities)
    const actions = Object.keys(srv.actions)
    if (!describe) return res.json ({ ...response, entities, actions })

    // Otherwise, return the description for the specified entities or actions.
    const chosen = describe === 'all' ? [ ...entities, ...actions ] : describe.split(',')
    chosen.forEach (each => {
      const d = srv.entities[each] || srv.actions[each]
      if (!d) return (response.unknown??=[]).push(each)
      const section = response [d.kind === 'entity' ? 'entities' : 'actions'] ??= {}
      const spec =  section[each] = { kind: d.kind }
      if (d.elements) spec.elements = squeezed (d.elements)
      if (d.params) spec.params = squeezed (d.params)
      if (d.returns) spec.returns = Object.values(squeezed ([d.returns]))[0]
    })
    return res.json (response)

    // Helper function to squeeze elements for concise representation
    function squeezed (elements, fks) {
      const response = {}
      for (let e of elements) {
        if (e['@odata.foreignKey4']) continue
        if (e.target) {
          let local = e.target.slice (srv.name.length + 1)
          if (!srv.entities[local]) continue
        }
        let spec = response[e.name] = {}
        if (e.key && !fks) spec.key = true
        if (e.items) { spec = spec.items = {}; e = e.items }
        if (e.type) spec.type =
          e.isComposition ? `Composition of ${e.is2many ? 'many ':''}${local(e.target)}` :
          e.isAssociation ? `Association to ${e.is2many ? 'many ':''}${local(e.target)}` :
          e.type.replace(/^cds\./,'')
        if (e.length) spec.type += `(${e.length})`
        if (e.elements) spec.elements = squeezed (e.elements)
        if (e.foreignKeys) spec.elements = squeezed (e.foreignKeys, 'fks')
      }
      return response
    }
    function local (name) {
      return name.startsWith(srv.name+'.') ? name.slice (srv.name.length + 1) : name
    }

  }


  /**
   * Handler for REST-style convenience shortcuts like GET /Books/201
   * @type {express.RequestHandler}
   */
  shortcut (req, res, next) {
    let { entity, id } = req.params, tail, body = req.body, srv =this.service
    if (entity in srv.actions) return this.action (req, res, next)

    if (req.method === 'GET') {
      if (entity.includes(' ')) [,entity,tail] = /^(\w+)( .*)?/.exec(entity)
      else if (id?.includes(' ')) [,id,tail] = /^(\w+)( .*)/.exec(id)
      else if (typeof body === 'string') [tail,body] = [body,undefined]
      const { SELECT } = cds.ql
      const q = req.body = tail?.length ? id ? SELECT (`from ${entity} [${id}] ${tail}`)
        : SELECT (`from ${entity} ${tail}`)
        : {SELECT: subject('from') }
      if (id !== undefined) q.SELECT.one = true //> ensures we reply 404 instead of 200 or 204
      if (typeof body === 'object') Object.assign (q.SELECT, body)
      if (typeof body === 'string') {
        let { from, ...clauses } = SELECT(`from x ${body}`).SELECT // eslint-disable-line no-unused-vars
        Object.assign (q.SELECT, clauses)
      }
    } else if (typeof body === 'string') {
      throw new cds.error (400, `Request body cannot be a string for ${req.method} requests.`)
    } else {
      switch (req.method) {
        case 'POST':   req.body = {INSERT:{ ...subject('into'), entries: [{...req.query,...body}] }}; break
        case 'PUT':    req.body = {UPSERT:{ ...subject('into'), entries: [{...req.query,...body}] }}; break
        case 'PATCH':  req.body = {UPDATE:{ ...subject('entity'), data: {...req.query,...body} }}; break
        case 'DELETE': req.body = {DELETE:{ ...subject('from') }}; break
      }
    }
    return next()

    /** Resolve the query's subject; expanding given id to {ID:id}, if any. */
    function subject (clause) {
      if (!id) return {[clause]: {ref:[entity]}}
      let target = srv.entities[entity] || cds.error (400, `Couldn't resolve target entity: ${entity}`)
      let keys = Object.keys (target.keys)
      if (keys.length !== 1) cds.error (400, `Target entity ${entity} must have exactly one key`)
      return {[clause]: {ref:[{ id:entity, where:[{ref:keys},'=',{val:id}] }]}, one:true }
    }
  }


  /**
   * Handler for custom actions and functions.
   * @type {express.RequestHandler}
   */
  action (req, res, next) {
    const { event } = req.params
    if (!(event in this.service.actions)) return next() //> CRUD /:entity/:id
    if (!(req.method in {GET:1,POST:2})) return next(501) //> only GET and POST allowed
    const data = { ...req.query, ...req.body }
    return this.exec ({ event, data, req, res }) .catch (next)
  }


  /**
   * Handler for all CRUD requests with CQN or CQL queries.
   * @type {express.RequestHandler}
   */
  query (req, res, next) {

    // Get query from request body
    const body = req.body || cds.error (400, `Request body is missing.`)
    const cqn = body.cqn || parse(body.cql) || parse(body) || body
    const q = this.valid (cqn)
    const $ = q[q.kind] // SELECT, INSERT, UPDATE, DELETE, ...

    // Apply additional request parameters to the query if present
    if (req.get('X-Total-Count')) $.count = true
    if (req.body.args) q.args = req.body.args

    // Turn SELECT where $search(...) into SELECT.search = [...]
    if ($.where?.[0].func === '$search') {
      $.search = $.where[0].args
      if ($.where.length === 1) delete $.where
      else $.where.splice (0, $.where[1] === '>' ? 4 : 2)
    }

    // Deviate to streaming if client accepts octet-stream
    if ($.stream || q.stream && req.headers.accept?.includes('application/octet-stream'))
      return this.stream(q,req) .catch (next)

    // Regular handling for non-streaming queries
    return this.exec(q,req) .catch (next)
  }


  /**
   * Validates a received and parsed query in CQN format.
   * @returns {object|undefined} the validated query or undefined if invalid
   */
  valid (qry) {
    const q = cds.ql(qry) || cds.error (400, `Not a valid query:`, q)
    if (q.SET) cds.error (400, `UNIONs are not supported.`)

    const $ = q[q.kind] || cds.error (400, `Not a valid query:`, q)

    const has_subselect = $.from?.SELECT
     || $.columns?.some(x => x.SELECT)
     || $.having?.some(x => x.SELECT)
     || $.where?.some(x => x.SELECT)
    if (has_subselect) cds.error (400, `SUBSELECTs are not supported.`)
    if ($.from?.join) cds.error (400, `JOINs are not supported.`)

    const srv = this.service
    if (srv.definition && cds.infer.target(q,srv)?.kind !== 'entity')
      cds.error (400, `Couldn't resolve target entity for query:`, q)

    const {allows} = cds.env.protocols.hcql
    if (q.SELECT || q.INSERT || q.UPSERT) ;
    else if (q.UPDATE && !allows.UPDATE.many) is_one(q,'entity')
    else if (q.DELETE && !allows.DELETE.many) is_one(q,'from')

    return q // looks good

    /** Ensure it's a to-one query */
    function is_one (q,subject) {
      let keys = new Set (Object.keys(q._target.keys)) // expects q._target has been inferred before
      let where = q[q.kind][subject]?.ref?.[0]?.where || $.where
      if (where?.length === 1 && where[0]?.val != undefined) return true //> ok
      if (where) for (;;) {
        let [ref,op,val,and] = where
        if (op !== '=' && op != '==') break
        if (ref?.ref == undefined) break; else keys.delete(ref.ref[0])
        if (val?.val == undefined) break
        if (!and) {
          if (keys.size === 0) return true //> ok
          else break
        }
        if (and.toLowerCase() !== 'and') break
        else where = where.slice(4)
      }
      throw new cds.error(403, `${q.kind} is allowed for single records only`) //> not ok
    }
  }


  /**
   * Central method to dispatch requests to the service and replying outcomes back to the client.
   * @param {{ event, data }} qed a query of request details
   * @param {express.Request} req the HTTP request object
   * @param {express.Response} res the HTTP response object
   * @returns {Promise<any>} results from service dispatch
   */
  async exec (qed, req = qed.req, res = qed.res || req.res) {
    const request = new cds.Request (qed.event ? qed : { query:qed, req, res })
    const results = await this.service.dispatch (request)
    if (res.headersSent) return //> response already sent by custom code
    if (results?.$count !== undefined) res.set ('X-Total-Count', results.$count)
    if (request.event === 'CREATE') res.status(201)
    if (request.messages == null && results == null)
      return qed.SELECT?.one ? cds.error(404) : res.sendStatus(204)
    else res.json (this.response4 ({ data: results, messages: request.messages }))
    return results
  }


  /**
   * Central method to execute streaming requests.
   * @param {express.Request} req the HTTP request object
   * @param {express.Response} res the HTTP response object
   * @returns {Promise<void>} as returned by the streaming pipeline
   */
  async stream (q, req, res = req.res) {
    const stream = await this.service.run (()=> q.bind(this.service).stream())
    res.set ('content-type', 'application/octet-stream')
    return pipeline (stream, res)
  }


  /**
   * Overrides base method to format responses according to HCQL expectations,
   * i.e. wrapping results in a `data` property and normalizing errors into
   * an `errors` array.
   */
  response4 (outcomes) {
    let { data, error, errors, messages } = super.response4 (outcomes)
    let response = {}
    if (data != null) { response.data = data
      if (data.affected !== undefined) response.affected = data.affected
      if (data.$count !== undefined) response.$count = data.$count
    }
    if (error) errors ??= error.details || [ error ]
    if (errors) response.errors = errors
    if (messages) response.messages = messages
    return response
  }
}


/**
 * Parses the request body as a CQL query if it is a string.
 * Returns the CQN or the original object if it is not a string.
 */
const parse = Object.assign (x => {
  if (typeof x === 'string') try { return parse.cql(x) } catch(e) {
    throw new cds.error (400, `Failed to parse CQL query: ${e.message}`, { query:x, cause:e })
  }
  else return x
}, { cql: (
  cds.env.ql.parser === 'cds-compiler' ? cds.parse.cql :
  cds.env.ql.parser === 'compatible' ? require('../../ql/core').cql :
  cds.env.ql.parser === 'cap.core' ? require('../../ql/core').cql :
  cds.parse.cql
)})


/**
 * Request logging middleware for HCQL adapter. Wrapped into an immediately
 * invoked function expression (IIFE) to keep outline views clean and tidy.
 */
const log_request = (()=>{

  const { YELLOW, GREEN, RESET, enabled:colors } = cds.utils.colors
  const { inspect:cqn, decodeURI } = cds.utils, o = { colors, depth:11 }
  const cql = x => {
    let [cmd] = /^SELECT|INSERT|UPDATE|UPSERT|DELETE|CALL/i.exec(x) || ['']
    return YELLOW + cmd.toUpperCase() + GREEN + x.slice(cmd.length) + RESET
  }

  /** @type {express.RequestHandler} */
  return function log_request (req, res, next) {
    LOG.info (req.method, decodeURI (req.baseUrl + req.path), (
      typeof req.body === 'object' ? cqn(req.body,o) :
      typeof req.body === 'string' ? cql(req.body) :
      req.body ?? ''
    ))
    next()
  }

})()


module.exports = HCQLAdapter
